$ua = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0.0.0 Safari/537.36"

foreach ($b in $books) {
    $outPath = "$outDir/$($b.file)"
    $fullUrl = $baseUrl + $b.url
    Write-Host "Downloading $($b.file) from $fullUrl"
    try {
        Invoke-WebRequest -Uri $fullUrl -UserAgent $ua -OutFile $outPath -TimeoutSec 30
        $size = (Get-Item $outPath).Length
        Write-Host "  OK: $size bytes"
    } catch {
        Write-Host "  FAILED: $_"
    }
    Start-Sleep -Seconds 2
}
Write-Host "Done!"
